import os
import importlib.util
import pytest

TARGET_CODE_PATH = os.environ['TARGET_CODE_PATH']
spec = importlib.util.spec_from_file_location('target_module', TARGET_CODE_PATH)
target = importlib.util.module_from_spec(spec)
spec.loader.exec_module(target)
make_acronym = target.make_acronym

def test_basic():
    assert make_acronym("Central Processing Unit") == "CPU"

def test_hyphenated():
    assert make_acronym("central-processing unit") == "CPU"

def test_mixed_case():
    assert make_acronym("hyperText Transfer Protocol") == "HTTP"

def test_numbers_punctuation():
    assert make_acronym("Version 2.0 release") == "VR"

def test_empty():
    assert make_acronym("") == ""

def test_no_alphabetic():
    assert make_acronym("123 456!!!") == ""

def test_type_error():
    with pytest.raises(TypeError):
        make_acronym(123)

def test_numeric_prefix():
    # "1st place" -> "st" is the alphabetic part.
    # Doc says numeric fragments should not prevent extracting alphabetic words.
    assert make_acronym("1st place") == "SP"

def test_single_letter_words():
    assert make_acronym("A B C") == "ABC"

