    base = {'a': 1}
    incoming = {'b': 2}
    result = merge_inventory(base, incoming)
    assert base == {'a': 1}
    assert incoming == {'b': 2}
    assert result == {'a': 1, 'b': 2}

def test_merge_inventory_invalid_count():
    base = {'a': 1}
    incoming = {'b': -1}
    with pytest.raises(ValueError):
        merge_inventory(base, incoming)

